    @Test
    void strictDecodeRejectsAlternativeEscapesAndSurrogates() {
        assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeRevokeRequestV1(
                utf8(REVOKE_REQUEST_JSON.replace("撤", "\\u64A4"))));
        for (String surrogate : List.of("\\uD800", "\\uDC00")) {
            assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeRevokeRequestV1(
                    utf8(REVOKE_REQUEST_JSON.replace("撤销原文", surrogate))));
        }
        String slash = REVOKE_REQUEST_JSON.replace("撤销原文", "slash/原文");
        assertEquals("slash/原文", MesEdhrSourceCreationCodec.decodeRevokeRequestV1(utf8(slash)).get("reason").textValue());
        assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeRevokeRequestV1(utf8(slash.replace("slash/", "slash\\/"))));
        String control = REVOKE_REQUEST_JSON.replace("撤销原文", "a\\u001Fb");
        assertEquals("a\u001Fb", MesEdhrSourceCreationCodec.decodeRevokeRequestV1(utf8(control)).get("reason").textValue());
        assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeRevokeRequestV1(utf8(control.replace("\\u001F", "\\u001f"))));
        assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeIssueRequestV1(utf8(ISSUE_REQUEST_JSON.replace("\\n", "\\u000A"))));
        String emoji = REVOKE_REQUEST_JSON.replace("撤销原文", "😀");
        assertEquals("😀", MesEdhrSourceCreationCodec.decodeRevokeRequestV1(utf8(emoji)).get("reason").textValue());
        assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeRevokeRequestV1(utf8(emoji.replace("😀", "\\uD83D\\uDE00"))));
    }

    @Test
    void evidenceUsesUnsignedUtf8OrderForBothTupleComponents() {
        for (String field : List.of("sourceType", "sourceId")) {
            ObjectNode privateUse = object(EVIDENCE_JSON);
            ObjectNode supplementary = object(EVIDENCE_JSON);
            privateUse.put(field, "\uE000");
            supplementary.put(field, "\uD800\uDC00");
            ObjectNode input = object(ISSUE_REQUEST_JSON);
            input.set("sourceEvidence", FIXTURE_MAPPER.createArrayNode().add(supplementary).add(privateUse));
            String originalValue = field.equals("sourceType") ? "ERP" : "9223372036854775807";
            String privateJson = EVIDENCE_JSON.replace("\"" + field + "\":\"" + originalValue + "\"", "\"" + field + "\":\"\uE000\"");
            String supplementaryJson = EVIDENCE_JSON.replace("\"" + field + "\":\"" + originalValue + "\"", "\"" + field + "\":\"\uD800\uDC00\"");
            String expected = ISSUE_REQUEST_JSON.replace("[" + EVIDENCE_JSON + "]", "[" + privateJson + "," + supplementaryJson + "]");
            assertEquals(expected, MesEdhrSourceCreationCodec.encodeIssueRequestV1(input).canonicalJson());
            assertEquals("\uE000", MesEdhrSourceCreationCodec.decodeIssueRequestV1(utf8(expected)).get("sourceEvidence").get(0).get(field).textValue());
            String reversed = ISSUE_REQUEST_JSON.replace("[" + EVIDENCE_JSON + "]", "[" + supplementaryJson + "," + privateJson + "]");
            assertThrows(IllegalArgumentException.class, () -> MesEdhrSourceCreationCodec.decodeIssueRequestV1(utf8(reversed)));
        }
    }

