    private static ObjectNode object(String json) {
        try {
            return (ObjectNode) FIXTURE_MAPPER.readTree(json);
        } catch (IOException e) {
            throw new AssertionError("Invalid literal test fixture", e);
        }
    }

    private static byte[] utf8(String value) { return value.getBytes(StandardCharsets.UTF_8); }

    private static List<String> keys(ObjectNode value) {
        List<String> result = new ArrayList<>();
        value.fieldNames().forEachRemaining(result::add);
        return result;
    }

    private static JsonNode reverseObjects(JsonNode value) {
        if (value.isObject()) {
            ObjectNode result = FIXTURE_MAPPER.createObjectNode();
            List<String> keys = keys((ObjectNode) value);
            Collections.reverse(keys);
            for (String key : keys) { result.set(key, reverseObjects(value.get(key))); }
            return result;
        }
        if (value.isArray()) {
            ArrayNode result = FIXTURE_MAPPER.createArrayNode();
            for (JsonNode item : value) { result.add(reverseObjects(item)); }
            return result;
        }
        return value.deepCopy();
    }

    private static List<String> objectPointers(JsonNode value) {
        List<String> pointers = new ArrayList<>();
        collectPointers(value, "", pointers);
        return pointers;
    }

    private static void collectPointers(JsonNode value, String pointer, List<String> result) {
        if (value.isObject()) {
            result.add(pointer);
            for (String key : keys((ObjectNode) value)) { collectPointers(value.get(key), pointer + "/" + key, result); }
        } else if (value.isArray()) {
            for (int i = 0; i < value.size(); i++) { collectPointers(value.get(i), pointer + "/" + i, result); }
        }
    }

    private static boolean isNullableEvidenceField(String pointer, String key) {
        return pointer.contains("/sourceEvidence/") && List.of("sourceObjectType", "sourceObjectId", "snapshotJson", "sourceIdentityKey", "relationReason").contains(key);
    }
